return ['domain'=>NULL,'plural-forms'=>'nplurals=6; plural=n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 && n%100<=99 ? 4 : 5;','language'=>'ar','project-id-version'=>'WordPress.com - Big Sky','pot-creation-date'=>'2026-09-16T17:25:55+00:00','po-revision-date'=>'2026-09-10 09:57:58+0000','x-generator'=>'GlotPress/2.4.0-alpha','messages'=>['Here is the visible area of the canvas. Photographs are shown as flat placeholder boxes at their real size, so treat any grey rectangle as an image that is present, not as a missing one.'=>'إليك الجزء المرئي من اللوحة. تُعرض الصور الفوتوغرافية على هيئة صناديق عنصر نائب ثابتة بحجمها الحقيقي، لذا تعامل مع أي مستطيل رمادي على أنه صورة موجودة، وليس صورة مفقودة.','Here is the canvas around %d block(s). Photographs are shown as flat placeholder boxes at their real size, so treat any grey rectangle as an image that is present, not as a missing one.'=>'إليك اللوحة المحيطة بـ %d من المكوّنات. تُعرض الصور الفوتوغرافية على هيئة صناديق عنصر نائب ثابتة بحجمها الحقيقي، لذا تعامل مع أي مستطيل رمادي على أنه صورة موجودة، وليس صورة مفقودة.','Here is the whole page, top to bottom. It is scaled down to fit, so body text will not be legible — read it for colour, type scale, spacing and section rhythm, and take an ordinary picture of a specific area when wording or fine detail matters. Photographs are shown as flat placeholder boxes at their real size.'=>'ها هي الصفحة كاملة، من الأعلى إلى الأسفل. تم تصغيرها لتتناسب مع المساحة المعروضة، لذا لن يكون النصّ الأساسي مقروءًا؛ استخدمه للاطلاع على الألوان، ومقياس الخط، والمسافات، وإيقاع الأقسام، والتقط صورة عادية لمنطقة محددة عندما تكون الصياغة أو التفاصيل الدقيقة مهمة. تُعرض الصور الفوتوغرافية على هيئة صناديق عنصر نائب ثابتة بحجمها الحقيقي.','I couldn\'t get a picture of the canvas just now.'=>'لم أستطع الحصول على صورة اللوحة الآن.','Takes a picture of the editor canvas as it currently renders, including unsaved changes. Use it to check how the page actually looks when the block data alone cannot answer that — after changing styles, colours, spacing or CSS, or whenever a reported problem is visual. Pass fullPage to see the whole page at once, which is what a theme or global styles change needs checking against. Photographs are replaced by flat placeholder boxes at their real size.'=>'يلتقط صورةً للوحة المحرر كما تظهر حاليًا، بما في ذلك التغييرات غير المحفوظة. استخدمه للتحقق من كيف تبدو الصفحة في الواقع عندما لا تتمكن بيانات المكوّن وحدها من الإجابة على ذلك — بعد تغيير الأنماط أو الألوان أو التباعد أو CSS أو عندما تكون المشكلة المبلغ عنها مرئية. مرّر fullPage لعرض الصفحة كاملةً دفعةً واحدة، وهو ما يلزم التحقّق منه عند إجراء تغييرات على القالب أو الأنماط العامة. تُستبدل الصور بصناديق عنصر نائب ثابتة بحجمها الحقيقي.','Capture Canvas'=>'التقاط اللوحة','Are there any changes you would like me to make?'=>'هل هناك أي تغييرات تود مني إجرائها؟','Your site is ready! Please click around and check it out.'=>'أصبح موقعك جاهزًا! يًرجى النقر حولها والتحقق منها.','Switching to edit mode so you can watch the new design being built.'=>'التبديل إلى وضع التحرير حتى تتمكن من مشاهدة التصميم الجديد الذي يتم إنشاؤه.','Return to WP Admin'=>'الرجوع إلى مسؤول ووردبريس','Personalize my site copy with my details.'=>'تخصيص محتوى موقعي باستخدام تفاصيلي.','Your changes could not be saved. Your work is still here — try saving again.'=>'تعذَّر حفظ التغييرات التي أجريتها. ما أنجزته لا يزال موجودًا هنا - حاول الحفظ مرة أخرى.','Some changes could not be saved. Your work is still here — try saving again.'=>'تعذَّر حفظ بعض التغييرات. ما أنجزته لا يزال موجودًا هنا - حاول الحفظ مرة أخرى.','Save your changes?'=>'هل تريد حفظ التغييرات التي أجريتها؟','You need to save or discard the changes to the current page.'=>'يتعين عليك حفظ التغييرات التي أجريتها على الصفحة الحالية أو تجاهلها.','The preview shows your saved site, so unsaved changes won’t appear there.'=>'تعرض المعاينة موقعك المحفوظ، لذا لن تظهر التغييرات غير المحفوظة هناك.','Save draft'=>'حفظ المسودة','Publish'=>'نشر','Redo'=>'إعادة'